SELECT ?zone ?temp ?setpoint WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_bot_ZN_4" .
  ?temp a brick:AirTemperature ; brick:isPartOf ?zone .
  ?setpoint a brick:Setpoint ; brick:isPartOf ?zone .
  FILTER(?setpoint != ?temp)
}

SELECT ?s ?cls ?serial ?lbl WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label "Perimeter_bot_ZN_4" .
  ?s a ?cls .
  ?s brick:isPartOf ?zone .
  OPTIONAL { ?s rdfs:label ?lbl }
}

SELECT ?s ?cls ?lbl WHERE {
  VALUES ?zone {
    http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z05
  }
  ?s a ?cls ; brick:isPartOf ?zone .
  OPTIONAL { ?s rdfs:label ?lbl }
}

SELECT ?s ?cls ?lbl ?ref ?tsid WHERE {
  ?s brick:isPartOf http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z05 .
  ?s a ?cls .
  OPTIONAL { ?s rdfs:label ?lbl }
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
}

SELECT ?s ?cls ?lbl ?tsid WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_4" .
  ?s a ?cls ; brick:isPartOf ?z .
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
}

SELECT ?s ?p ?o WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_bot_ZN_4" .
  ?s ?p ?o .
  FILTER(?s != ?z)
}

SELECT ?s ?p ?o WHERE {
  ?s a brick:Zone .
  ?s rdfs:label ?o .
  FILTER (CONTAINS(?o, "Perimeter_bot_ZN_4"))
  FILTER (STRLEN(?o) = 20)
}

SELECT ?s ?p ?o WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_4" .
  ?s brick:isPartOf ?z .
  OPTIONAL { ?s a ?p . ?s rdfs:label ?o }
}

SELECT ?s WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_4" .
  ?t a brick:AirTemperature ; brick:isPartOf ?z .
}

SELECT ?s ?cls ?lbl WHERE {
  ?s a ?cls ; brick:isPartOf http://buildgraph.org/BG_large_office_2004_0000#Room_F2_R031 .
  OPTIONAL { ?s rdfs:label ?lbl }
}

